import pandas as pd


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    if name in inputs:
        return inputs[name]
    lower_map = {k.lower(): k for k in inputs.keys()}
    if name.lower() in lower_map:
        return inputs[lower_map[name.lower()]]
    raise KeyError(f"Could not find input '{name}' in provided inputs: {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_CUSTOMER").copy()
    stg = _get_input(inputs, "STG_CUSTOMER").copy()
    fact = _get_input(inputs, "FACT_TXN").copy()

    dim_out = dim.copy()

    # Build map of customer_id -> index of its current row (is_current == 1)
    current_map = {}
    for idx, row in dim_out[dim_out["is_current"] == 1].iterrows():
        current_map[row["customer_id"]] = idx

    # Determine max surrogate key prior to this load
    if not dim_out.empty and dim_out["customer_sk"].notna().any():
        max_sk = dim_out["customer_sk"].max()
    else:
        max_sk = 0
    if pd.isna(max_sk):
        max_sk = 0

    def segments_differ(a, b):
        a_null = pd.isna(a)
        b_null = pd.isna(b)
        if a_null and b_null:
            return False
        if a_null or b_null:
            return True
        return a != b

    # Decide which staged records create a new version
    creating_rows = []
    for idx, srow in stg.iterrows():
        cid = srow["customer_id"]
        if cid in current_map:
            cur_idx = current_map[cid]
            cur_segment = dim_out.at[cur_idx, "segment"]
            if segments_differ(cur_segment, srow["segment"]):
                creating_rows.append((cid, srow))
        else:
            creating_rows.append((cid, srow))

    # Row numbering is over creating staged records only, ordered by customer_id
    creating_rows_sorted = sorted(creating_rows, key=lambda x: x[0])

    new_rows = []
    for i, (cid, srow) in enumerate(creating_rows_sorted, start=1):
        new_sk = max_sk + i

        # Expire prior current row, if any
        if cid in current_map:
            cur_idx = current_map[cid]
            dim_out.at[cur_idx, "eff_end_date"] = srow["update_date"]
            dim_out.at[cur_idx, "is_current"] = 0

        new_rows.append(
            {
                "customer_sk": new_sk,
                "customer_id": cid,
                "segment": srow["segment"],
                "eff_start_date": srow["update_date"],
                "eff_end_date": pd.NaT,
                "is_current": 1,
            }
        )

    if new_rows:
        new_df = pd.DataFrame(new_rows)
        dim_out = pd.concat([dim_out, new_df], ignore_index=True)
    else:
        dim_out = dim_out.reset_index(drop=True)

    # Step 2: key the facts against the updated dimension
    def find_sk(cid, txn_date):
        if pd.isna(cid) or pd.isna(txn_date):
            return -1
        candidates = dim_out[dim_out["customer_id"] == cid]
        for _, r in candidates.iterrows():
            start = r["eff_start_date"]
            end = r["eff_end_date"]
            if pd.isna(start):
                continue
            if start <= txn_date and (pd.isna(end) or txn_date < end):
                return r["customer_sk"]
        return -1

    fact_out = fact.copy()
    fact_out["customer_sk"] = fact_out.apply(
        lambda row: find_sk(row["customer_id"], row["txn_date"]), axis=1
    )

    fact_keyed = fact_out[["txn_id", "customer_sk", "amount"]].copy()

    return {"dim_customer_out": dim_out, "fact_txn_keyed": fact_keyed}
